-- E-commerce dataset: 20,000 rows with intentional NULL values
-- MySQL 8.0+ compatible. Import/run this file in MySQL Workbench.

CREATE DATABASE IF NOT EXISTS ecommerce_project;
USE ecommerce_project;

DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
    order_id INT PRIMARY KEY,
    customer_id INT NOT NULL,
    customer_name VARCHAR(80) NULL,
    city VARCHAR(50) NULL,
    product_name VARCHAR(100) NULL,
    category VARCHAR(50) NULL,
    quantity INT NULL,
    unit_price DECIMAL(10,2) NULL,
    discount_percent DECIMAL(5,2) NULL,
    payment_method VARCHAR(40) NULL,
    order_date DATE NULL,
    order_status VARCHAR(30) NULL,
    rating TINYINT NULL
);









































-- Quick validation queries
SELECT COUNT(*) AS total_rows FROM orders;



SELECT COUNT(*) AS rows_with_any_null
FROM orders
WHERE customer_name IS NULL OR city IS NULL OR product_name IS NULL
   OR category IS NULL OR quantity IS NULL OR unit_price IS NULL
   OR discount_percent IS NULL OR payment_method IS NULL
   OR order_date IS NULL OR order_status IS NULL OR rating IS NULL;
   
   
   
SELECT category, COUNT(*) AS order_count
FROM orders
GROUP BY category
ORDER BY order_count DESC;


SELECT order_status, COUNT(*) AS status_count
FROM orders
GROUP BY order_status;

/*
============================================================
E-COMMERCE SQL PROJECT: BEGINNER TO ADVANCED
Database: ecommerce_project
Table: orders
Dialect: MySQL 8.0+
Dataset: 20,000 orders; selected columns contain NULLs
============================================================

HOW TO USE
1. Run ecommerce_20000.sql first.
2. Open this file in MySQL Workbench.
3. Run sections in order. Each question is followed by its query.
4. Some questions have more than one valid solution.
*/

USE ecommerce_project;

-- ==========================================================
-- 0. DATABASE, TABLE STRUCTURE, AND DATA VALIDATION
-- ==========================================================

-- Q1. Which database is currently selected?
SELECT DATABASE() AS current_database;

-- Q2. List all tables in this database.
SHOW TABLES;

-- Q3. Inspect the table's columns and data types.
DESCRIBE orders;

-- Q4. Show the SQL used to create the table.
SHOW CREATE TABLE orders;

-- Q5. How many rows are in the table?
SELECT COUNT(*) AS total_orders
FROM orders;

-- Q6. Show 10 sample rows.
SELECT *
FROM orders
LIMIT 10;

-- Q7. How many distinct customers are represented?
SELECT COUNT(DISTINCT customer_id) AS unique_customers
FROM orders;

-- Q8. Check whether order_id is unique.
SELECT order_id, COUNT(*) AS occurrences
FROM orders
GROUP BY order_id
HAVING COUNT(*) > 1;


-- ==========================================================
-- 1. BASIC SELECT, ALIASES, DISTINCT, LIMIT, SORTING
-- ==========================================================

-- Q9. Display order ID, customer, product, and status.
SELECT order_id, customer_name, product_name, order_status
FROM orders;

-- Q10. Show each product category only once.
SELECT DISTINCT category
FROM orders
ORDER BY category;

-- Q11. Show the 10 most expensive orders by unit price.
SELECT order_id, product_name, unit_price
FROM orders
WHERE unit_price IS NOT NULL
ORDER BY unit_price DESC
LIMIT 10;

-- Q12. Show the 10 most recent orders with a known date.
SELECT order_id, customer_id, order_date
FROM orders
WHERE order_date IS NOT NULL
ORDER BY order_date DESC
LIMIT 10;

-- Q13. Display a calculated line value before discount.
SELECT order_id, product_name, quantity, unit_price,
       quantity * unit_price AS gross_value
FROM orders
WHERE quantity IS NOT NULL AND unit_price IS NOT NULL;


-- ==========================================================
-- 2. WHERE, COMPARISON, LOGICAL OPERATORS, BETWEEN, IN, LIKE
-- ==========================================================

-- Q14. Find orders with a unit price greater than 10,000.
SELECT *
FROM orders
WHERE unit_price > 10000;

-- Q15. Find orders whose status is Delivered.
SELECT *
FROM orders
WHERE order_status = 'Delivered';

-- Q16. Find orders that are Delivered or Shipped.
SELECT order_id, order_status, order_date
FROM orders
WHERE order_status IN ('Delivered', 'Shipped');

-- Q17. Find products priced between 500 and 5,000.
SELECT order_id, product_name, unit_price
FROM orders
WHERE unit_price BETWEEN 500 AND 5000;

-- Q18. Find orders with a discount of at least 20%.
SELECT order_id, discount_percent, product_name
FROM orders
WHERE discount_percent >= 20;

-- Q19. Find product names containing the word 'SQL'.
SELECT *
FROM orders
WHERE product_name LIKE '%SQL%';

-- Q20. Find customers whose names start with 'A'.
SELECT order_id, customer_name
FROM orders
WHERE customer_name LIKE 'A%';

-- Q21. Find orders not cancelled.
SELECT *
FROM orders
WHERE order_status <> 'Cancelled';

-- Q22. Find orders with quantity 1, 2, or 3.
SELECT order_id, quantity
FROM orders
WHERE quantity IN (1, 2, 3);

-- Q23. Combine conditions: delivered orders with a rating of 4 or 5.
SELECT order_id, order_status, rating
FROM orders
WHERE order_status = 'Delivered'
  AND rating IN (4, 5);


-- ==========================================================
-- 3. NULL HANDLING: IS NULL, IS NOT NULL, IFNULL, COALESCE
-- ==========================================================

-- Q24. Find rows where city is missing.
SELECT *
FROM orders
WHERE city IS NULL;

-- Q25. Find rows where city is present.
SELECT *
FROM orders
WHERE city IS NOT NULL;

-- Q26. Count missing values in each selected column.
SELECT
  SUM(customer_name IS NULL) AS missing_customer_name,
  SUM(city IS NULL) AS missing_city,
  SUM(product_name IS NULL) AS missing_product_name,
  SUM(category IS NULL) AS missing_category,
  SUM(quantity IS NULL) AS missing_quantity,
  SUM(unit_price IS NULL) AS missing_unit_price,
  SUM(discount_percent IS NULL) AS missing_discount,
  SUM(payment_method IS NULL) AS missing_payment_method,
  SUM(order_date IS NULL) AS missing_order_date,
  SUM(order_status IS NULL) AS missing_order_status,
  SUM(rating IS NULL) AS missing_rating
FROM orders;

-- Q27. Display missing city as 'Unknown' without changing stored data.
SELECT order_id, COALESCE(city, 'Unknown') AS city_display
FROM orders;

-- Q28. Treat a missing discount as 0 for this calculation.
SELECT order_id,
       unit_price,
       discount_percent,
       unit_price * (1 - COALESCE(discount_percent, 0) / 100) AS price_after_discount
FROM orders
WHERE unit_price IS NOT NULL;

-- Q29. Find rows where any of the main descriptive fields are missing.
SELECT *
FROM orders
WHERE customer_name IS NULL
   OR city IS NULL
   OR product_name IS NULL
   OR category IS NULL
   OR quantity IS NULL
   OR unit_price IS NULL;

-- Q30. Compare total rows with rows that have a known rating.
SELECT COUNT(*) AS all_rows,
       COUNT(rating) AS rows_with_rating,
       COUNT(*) - COUNT(rating) AS rows_without_rating
FROM orders;


-- ==========================================================
-- 4. STRING FUNCTIONS AND VARCHAR
-- ==========================================================

-- Q31. Show the length of each customer name.
SELECT customer_name, CHAR_LENGTH(customer_name) AS name_length
FROM orders
WHERE customer_name IS NOT NULL
LIMIT 25;

-- Q32. Convert customer names to uppercase.
SELECT UPPER(customer_name) AS customer_name_upper
FROM orders
WHERE customer_name IS NOT NULL
LIMIT 25;

-- Q33. Convert city names to lowercase.
SELECT LOWER(city) AS city_lower
FROM orders
WHERE city IS NOT NULL
LIMIT 25;

-- Q34. Remove extra spaces around city values (display only).
SELECT city, TRIM(city) AS cleaned_city
FROM orders
WHERE city IS NOT NULL;

-- Q35. Combine customer and city into one label.
SELECT CONCAT(COALESCE(customer_name, 'Unknown customer'),
              ' - ',
              COALESCE(city, 'Unknown city')) AS customer_location
FROM orders;

-- Q36. Extract the first 3 characters of a product name.
SELECT product_name, LEFT(product_name, 3) AS product_prefix
FROM orders
WHERE product_name IS NOT NULL
LIMIT 25;

-- Q37. Replace missing product names for display.
SELECT order_id, IFNULL(product_name, 'Product not recorded') AS product_display
FROM orders;

-- Q38. Find customer names containing 'Kumar'.
SELECT *
FROM orders
WHERE customer_name LIKE '%Kumar%';


-- ==========================================================
-- 5. NUMERIC FUNCTIONS AND CALCULATED COLUMNS
-- ==========================================================

-- Q39. Calculate gross order value (quantity × unit price).
SELECT order_id, quantity, unit_price,
       quantity * unit_price AS gross_value
FROM orders
WHERE quantity IS NOT NULL AND unit_price IS NOT NULL;

-- Q40. Calculate net value after discount, treating NULL discount as zero.
SELECT order_id,
       quantity * unit_price AS gross_value,
       COALESCE(discount_percent, 0) AS discount_used,
       quantity * unit_price * (1 - COALESCE(discount_percent, 0) / 100) AS net_value
FROM orders
WHERE quantity IS NOT NULL AND unit_price IS NOT NULL;

-- Q41. Round calculated net value to 2 decimal places.
SELECT order_id,
       ROUND(quantity * unit_price *
             (1 - COALESCE(discount_percent, 0) / 100), 2) AS net_value
FROM orders
WHERE quantity IS NOT NULL AND unit_price IS NOT NULL;

-- Q42. Find orders with an even order ID.
SELECT order_id
FROM orders
WHERE MOD(order_id, 2) = 0;

-- Q43. Show unit price rounded to the nearest 100.
SELECT order_id, unit_price, ROUND(unit_price, -2) AS rounded_price
FROM orders
WHERE unit_price IS NOT NULL;


-- ==========================================================
-- 6. DATE FUNCTIONS
-- ==========================================================

-- Q44. Show the year and month of each dated order.
SELECT order_id, order_date,
       YEAR(order_date) AS order_year,
       MONTH(order_date) AS order_month
FROM orders
WHERE order_date IS NOT NULL;

-- Q45. Count orders by year.
SELECT YEAR(order_date) AS order_year, COUNT(*) AS order_count
FROM orders
WHERE order_date IS NOT NULL
GROUP BY YEAR(order_date)
ORDER BY order_year;

-- Q46. Count orders by month.
SELECT DATE_FORMAT(order_date, '%Y-%m') AS order_month,
       COUNT(*) AS order_count
FROM orders
WHERE order_date IS NOT NULL
GROUP BY DATE_FORMAT(order_date, '%Y-%m')
ORDER BY order_month;

-- Q47. Find orders placed in January 2026.
SELECT *
FROM orders
WHERE order_date >= '2026-01-01'
  AND order_date < '2026-02-01';

-- Q48. Find how many days have passed since each order (relative to today).
SELECT order_id, order_date,
       DATEDIFF(CURDATE(), order_date) AS days_since_order
FROM orders
WHERE order_date IS NOT NULL;

-- Q49. Group orders by weekday.
SELECT DAYNAME(order_date) AS weekday_name, COUNT(*) AS order_count
FROM orders
WHERE order_date IS NOT NULL
GROUP BY DAYOFWEEK(order_date), DAYNAME(order_date)
ORDER BY DAYOFWEEK(order_date);


-- ==========================================================
-- 7. AGGREGATE FUNCTIONS, GROUP BY, HAVING
-- ==========================================================

-- Q50. Find the lowest, highest, average, and total unit price.
SELECT MIN(unit_price) AS min_price,
       MAX(unit_price) AS max_price,
       ROUND(AVG(unit_price), 2) AS average_price,
       SUM(unit_price) AS sum_of_unit_prices
FROM orders;

-- Q51. Count orders by status.
SELECT order_status, COUNT(*) AS order_count
FROM orders
GROUP BY order_status
ORDER BY order_count DESC;

-- Q52. Count orders by category.
SELECT category, COUNT(*) AS order_count
FROM orders
GROUP BY category
ORDER BY order_count DESC;

-- Q53. Calculate average product price by category.
SELECT category, ROUND(AVG(unit_price), 2) AS average_price
FROM orders
GROUP BY category
ORDER BY average_price DESC;

-- Q54. Find cities with more than 500 orders.
SELECT city, COUNT(*) AS order_count
FROM orders
GROUP BY city
HAVING COUNT(*) > 500
ORDER BY order_count DESC;

-- Q55. Find categories with average unit price above 5,000.
SELECT category, ROUND(AVG(unit_price), 2) AS average_price
FROM orders
GROUP BY category
HAVING AVG(unit_price) > 5000;

-- Q56. Count orders and calculate total gross value by payment method.
SELECT payment_method,
       COUNT(*) AS order_count,
       SUM(quantity * unit_price) AS gross_value
FROM orders
GROUP BY payment_method
ORDER BY gross_value DESC;

-- Q57. Calculate rating counts and average rating by category.
SELECT category,
       COUNT(rating) AS rated_orders,
       ROUND(AVG(rating), 2) AS average_rating
FROM orders
GROUP BY category
ORDER BY average_rating DESC;


-- ==========================================================
-- 8. CASE EXPRESSIONS AND CONDITIONAL AGGREGATION
-- ==========================================================

-- Q58. Categorize unit prices as Budget, Mid-range, or Premium.
SELECT order_id, product_name, unit_price,
       CASE
         WHEN unit_price IS NULL THEN 'Unknown'
         WHEN unit_price < 500 THEN 'Budget'
         WHEN unit_price < 5000 THEN 'Mid-range'
         ELSE 'Premium'
       END AS price_band
FROM orders;

-- Q59. Count orders by status using conditional aggregation.
SELECT
  SUM(order_status = 'Delivered') AS delivered_count,
  SUM(order_status = 'Cancelled') AS cancelled_count,
  SUM(order_status = 'Returned') AS returned_count,
  SUM(order_status = 'Shipped') AS shipped_count,
  SUM(order_status = 'Processing') AS processing_count
FROM orders;

-- Q60. Label ratings as Low, Average, or High.
SELECT order_id, rating,
       CASE
         WHEN rating IS NULL THEN 'Not rated'
         WHEN rating <= 2 THEN 'Low'
         WHEN rating = 3 THEN 'Average'
         ELSE 'High'
       END AS rating_group
FROM orders;


-- ==========================================================
-- 9. JOINS
-- The dataset currently has one table. These queries create
-- small supporting tables so you can practise JOINs.
-- ==========================================================

CREATE TABLE IF NOT EXISTS category_targets (
    category VARCHAR(50) PRIMARY KEY,
    target_orders INT NOT NULL
);

ON DUPLICATE KEY UPDATE target_orders = VALUES(target_orders);

-- Q61. INNER JOIN: show categories that exist in both tables.
SELECT o.category, COUNT(*) AS actual_orders, ct.target_orders
FROM orders o
INNER JOIN category_targets ct ON o.category = ct.category
GROUP BY o.category, ct.target_orders;

-- Q62. LEFT JOIN: keep all categories in the target table.
SELECT ct.category, ct.target_orders, COUNT(o.order_id) AS actual_orders
FROM category_targets ct
LEFT JOIN orders o ON o.category = ct.category
GROUP BY ct.category, ct.target_orders;

-- Q63. RIGHT JOIN: keep every category target row.
SELECT o.category, o.order_id, ct.category AS target_category, ct.target_orders
FROM orders o
RIGHT JOIN category_targets ct ON o.category = ct.category
LIMIT 50;

-- Q64. SELF JOIN: pair different orders made by the same customer.
-- LIMIT keeps the output manageable.
SELECT a.customer_id,
       a.order_id AS order_one,
       b.order_id AS order_two
FROM orders a
JOIN orders b
  ON a.customer_id = b.customer_id
 AND a.order_id < b.order_id
LIMIT 100;

-- Q65. CROSS JOIN: show all possible category/target combinations.
SELECT ct.category, ct.target_orders, p.payment_method
FROM category_targets ct
CROSS JOIN (
    SELECT DISTINCT payment_method
    FROM orders
    WHERE payment_method IS NOT NULL
) AS p
LIMIT 100;


-- ==========================================================
-- 10. UNION AND UNION ALL
-- ==========================================================

-- Q66. UNION: combine customer and city names into one list,
-- removing duplicate values.
SELECT customer_name AS item
FROM orders
WHERE customer_name IS NOT NULL
UNION
SELECT city AS item
FROM orders
WHERE city IS NOT NULL
ORDER BY item;

-- Q67. UNION ALL: combine two order lists and retain duplicates.
SELECT order_id, 'High value' AS order_group
FROM orders
WHERE unit_price >= 10000
UNION ALL
SELECT order_id, 'Discounted' AS order_group
FROM orders
WHERE discount_percent >= 20;

-- Q68. Compare UNION and UNION ALL counts.
SELECT COUNT(*) AS combined_rows_with_duplicates
FROM (
    SELECT customer_id FROM orders
    UNION ALL
    SELECT customer_id FROM orders
) AS u;

SELECT COUNT(*) AS combined_distinct_customers
FROM (
    SELECT customer_id FROM orders
    UNION
    SELECT customer_id FROM orders
) AS u;


-- ==========================================================
-- 11. SUBQUERIES
-- ==========================================================

-- Q69. Find orders priced above the overall average price.
SELECT order_id, product_name, unit_price
FROM orders
WHERE unit_price > (SELECT AVG(unit_price) FROM orders);

-- Q70. Find the most expensive order(s) by unit price.
SELECT order_id, product_name, unit_price
FROM orders
WHERE unit_price = (SELECT MAX(unit_price) FROM orders);

-- Q71. Find orders from customers who have placed more than 5 orders.
SELECT *
FROM orders
WHERE customer_id IN (
    SELECT customer_id
    FROM orders
    GROUP BY customer_id
    HAVING COUNT(*) > 5
);

-- Q72. Find categories whose average price is above the overall average.
SELECT category, AVG(unit_price) AS category_average
FROM orders
GROUP BY category
HAVING AVG(unit_price) > (SELECT AVG(unit_price) FROM orders);

-- Q73. Correlated subquery: orders priced above their category's average.
SELECT o.order_id, o.category, o.product_name, o.unit_price
FROM orders o
WHERE o.category IS NOT NULL
  AND o.unit_price > (
      SELECT AVG(i.unit_price)
      FROM orders i
      WHERE i.category = o.category
  );


-- ==========================================================
-- 12. COMMON TABLE EXPRESSIONS (CTEs)
-- ==========================================================

-- Q74. Use a CTE to calculate gross value for each order.
WITH order_values AS (
    SELECT order_id, quantity, unit_price,
           quantity * unit_price AS gross_value
    FROM orders
    WHERE quantity IS NOT NULL AND unit_price IS NOT NULL
)
SELECT *
FROM order_values
ORDER BY gross_value DESC
LIMIT 20;

-- Q75. Use a CTE to find category-level sales value.
WITH category_sales AS (
    SELECT category,
           SUM(quantity * unit_price *
               (1 - COALESCE(discount_percent, 0) / 100)) AS net_value
    FROM orders
    WHERE quantity IS NOT NULL AND unit_price IS NOT NULL
    GROUP BY category
)
SELECT category, ROUND(net_value, 2) AS net_value
FROM category_sales
ORDER BY net_value DESC;

-- Q76. Use multiple CTEs to compare each category to the overall average.
WITH category_average AS (
    SELECT category, AVG(unit_price) AS avg_price
    FROM orders
    WHERE category IS NOT NULL
    GROUP BY category
),
overall_average AS (
    SELECT AVG(unit_price) AS avg_price
    FROM orders
)
SELECT ca.category,
       ROUND(ca.avg_price, 2) AS category_avg_price,
       ROUND(oa.avg_price, 2) AS overall_avg_price
FROM category_average ca
CROSS JOIN overall_average oa
ORDER BY ca.avg_price DESC;

-- Q77. Recursive CTE: generate numbers 1 to 10 (MySQL 8+).
WITH RECURSIVE numbers AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1
    FROM numbers
    WHERE n < 10
)
SELECT n
FROM numbers;


-- ==========================================================
-- 13. WINDOW FUNCTIONS
-- ==========================================================

-- Q78. Rank orders by unit price from highest to lowest.
SELECT order_id, product_name, unit_price,
       RANK() OVER (ORDER BY unit_price DESC) AS price_rank
FROM orders
WHERE unit_price IS NOT NULL
LIMIT 100;

-- Q79. Compare ROW_NUMBER, RANK, and DENSE_RANK.
SELECT order_id, unit_price,
       ROW_NUMBER() OVER (ORDER BY unit_price DESC) AS row_num,
       RANK() OVER (ORDER BY unit_price DESC) AS price_rank,
       DENSE_RANK() OVER (ORDER BY unit_price DESC) AS dense_price_rank
FROM orders
WHERE unit_price IS NOT NULL
LIMIT 100;

-- Q80. Rank products within each category by price.
SELECT order_id, category, product_name, unit_price,
       RANK() OVER (
           PARTITION BY category
           ORDER BY unit_price DESC
       ) AS category_price_rank
FROM orders
WHERE category IS NOT NULL AND unit_price IS NOT NULL;

-- Q81. Find each customer's order sequence.
SELECT customer_id, order_id, order_date,
       ROW_NUMBER() OVER (
           PARTITION BY customer_id
           ORDER BY order_date, order_id
       ) AS customer_order_number
FROM orders
WHERE order_date IS NOT NULL;

-- Q82. Show each order's price and its customer's average price.
SELECT order_id, customer_id, unit_price,
       ROUND(AVG(unit_price) OVER (PARTITION BY customer_id), 2) AS customer_avg_price
FROM orders
WHERE unit_price IS NOT NULL;

-- Q83. Running count of orders over time.
SELECT order_id, order_date,
       COUNT(*) OVER (
           ORDER BY order_date, order_id
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_order_count
FROM orders
WHERE order_date IS NOT NULL;

-- Q84. Running gross value over time.
SELECT order_id, order_date, quantity, unit_price,
       SUM(quantity * unit_price) OVER (
           ORDER BY order_date, order_id
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_gross_value
FROM orders
WHERE order_date IS NOT NULL
  AND quantity IS NOT NULL
  AND unit_price IS NOT NULL;

-- Q85. Compare each order's price to the previous order's price.
SELECT order_id, order_date, unit_price,
       LAG(unit_price) OVER (ORDER BY order_date, order_id) AS previous_order_price,
       unit_price - LAG(unit_price) OVER (ORDER BY order_date, order_id) AS price_difference
FROM orders
WHERE order_date IS NOT NULL AND unit_price IS NOT NULL;

-- Q86. Show the next order's date for each customer.
SELECT customer_id, order_id, order_date,
       LEAD(order_date) OVER (
           PARTITION BY customer_id
           ORDER BY order_date, order_id
       ) AS next_order_date
FROM orders
WHERE order_date IS NOT NULL;

-- Q87. Show the top 3 priced orders in each category using a CTE + window function.
WITH ranked_orders AS (
    SELECT order_id, category, product_name, unit_price,
           ROW_NUMBER() OVER (
               PARTITION BY category
               ORDER BY unit_price DESC, order_id
           ) AS rn
    FROM orders
    WHERE category IS NOT NULL AND unit_price IS NOT NULL
)
SELECT order_id, category, product_name, unit_price, rn
FROM ranked_orders
WHERE rn <= 3
ORDER BY category, rn;

-- Q88. Calculate each category's percentage of total gross value.
WITH order_values AS (
    SELECT category, quantity * unit_price AS gross_value
    FROM orders
    WHERE category IS NOT NULL AND quantity IS NOT NULL AND unit_price IS NOT NULL
)
SELECT category,
       ROUND(SUM(gross_value), 2) AS category_gross_value,
       ROUND(100 * SUM(gross_value) / SUM(SUM(gross_value)) OVER (), 2) AS pct_of_total
FROM order_values
GROUP BY category
ORDER BY category_gross_value DESC;


-- ==========================================================
-- 14. VIEWS
-- ==========================================================

-- Q89. Create a view of orders with complete core fields.
CREATE OR REPLACE VIEW complete_orders AS
SELECT *
FROM orders
WHERE customer_id IS NOT NULL
  AND product_name IS NOT NULL
  AND category IS NOT NULL
  AND quantity IS NOT NULL
  AND unit_price IS NOT NULL
  AND order_date IS NOT NULL;

-- Q90. Query the view.
SELECT *
FROM complete_orders
LIMIT 100;

-- Q91. Count complete orders by category.
SELECT category, COUNT(*) AS complete_order_count
FROM complete_orders
GROUP BY category
ORDER BY complete_order_count DESC;


-- ==========================================================
-- 15. TEMPORARY TABLES
-- ==========================================================

-- Q92. Create a temporary table of delivered orders with known prices.
DROP TEMPORARY TABLE IF EXISTS delivered_orders;
CREATE TEMPORARY TABLE delivered_orders AS
SELECT order_id, customer_id, category, quantity, unit_price, order_date
FROM orders
WHERE order_status = 'Delivered'
  AND quantity IS NOT NULL
  AND unit_price IS NOT NULL;

-- Q93. Summarize the temporary table.
SELECT category,
       COUNT(*) AS delivered_count,
       ROUND(SUM(quantity * unit_price), 2) AS delivered_gross_value
FROM delivered_orders
GROUP BY category
ORDER BY delivered_gross_value DESC;


-- ==========================================================
-- 16. DATA QUALITY AND CLEANING PRACTICE
-- Queries in this section inspect data or create cleaned output;
-- they do not overwrite the original values.
-- ==========================================================

-- Q94. Count rows with any missing values in selected columns.
SELECT COUNT(*) AS rows_with_missing_values
FROM orders
WHERE customer_name IS NULL
   OR city IS NULL
   OR product_name IS NULL
   OR category IS NULL
   OR quantity IS NULL
   OR unit_price IS NULL
   OR discount_percent IS NULL
   OR payment_method IS NULL
   OR order_date IS NULL
   OR order_status IS NULL
   OR rating IS NULL;

-- Q95. Return a cleaned display with fallback labels and values.
SELECT order_id,
       COALESCE(customer_name, 'Unknown customer') AS customer_name,
       COALESCE(city, 'Unknown city') AS city,
       COALESCE(product_name, 'Unknown product') AS product_name,
       COALESCE(category, 'Uncategorized') AS category,
       quantity,
       unit_price,
       COALESCE(discount_percent, 0) AS discount_percent,
       COALESCE(payment_method, 'Unknown') AS payment_method,
       order_date,
       COALESCE(order_status, 'Unknown') AS order_status,
       rating
FROM orders;

-- Q96. Check for impossible values (expected to return no rows unless data is changed).
SELECT *
FROM orders
WHERE quantity < 0
   OR unit_price < 0
   OR discount_percent < 0
   OR discount_percent > 100
   OR rating < 1
   OR rating > 5;

-- Q97. Find possible duplicate orders based on customer, product, date, and quantity.
SELECT customer_id, product_name, order_date, quantity, COUNT(*) AS similar_rows
FROM orders
GROUP BY customer_id, product_name, order_date, quantity
HAVING COUNT(*) > 1
ORDER BY similar_rows DESC;


-- ==========================================================
-- 17. INDEXES AND EXPLAIN
-- ==========================================================

-- Q98. Create indexes to support common filters and joins.
-- If you run this section more than once, MySQL may report that
-- the index already exists; that is expected.
CREATE INDEX idx_orders_customer_id ON orders(customer_id);
CREATE INDEX idx_orders_order_date ON orders(order_date);
CREATE INDEX idx_orders_category ON orders(category);
CREATE INDEX idx_orders_status ON orders(order_status);

-- Q99. Inspect the query execution plan.
EXPLAIN
SELECT order_id, customer_id, order_date
FROM orders
WHERE customer_id = 1500;

-- Q100. Inspect an aggregate query's execution plan.
EXPLAIN
SELECT category, COUNT(*)
FROM orders
GROUP BY category;


-- ==========================================================
-- 18. TRANSACTIONS AND SAFE UPDATE PRACTICE
-- ==========================================================

-- Q101. Demonstrate a transaction without changing persistent data.
START TRANSACTION;
SELECT COUNT(*) AS cancelled_orders
FROM orders
WHERE order_status = 'Cancelled';
ROLLBACK;

-- Q102. Demonstrate a safe update inside a transaction, then undo it.
-- This updates one chosen row temporarily and ROLLBACK restores it.
START TRANSACTION;
UPDATE orders
SET order_status = 'Processing'
WHERE order_id = 1;
SELECT order_id, order_status
FROM orders
WHERE order_id = 1;
ROLLBACK;

-- Q103. Confirm the original value after rollback.
SELECT order_id, order_status
FROM orders
WHERE order_id = 1;


-- ==========================================================
-- 19. BUSINESS ANALYSIS QUESTIONS
-- ==========================================================

-- Q104. Which categories have the greatest estimated net value?
SELECT category,
       ROUND(SUM(quantity * unit_price *
           (1 - COALESCE(discount_percent, 0) / 100)), 2) AS estimated_net_value
FROM orders
WHERE category IS NOT NULL
  AND quantity IS NOT NULL
  AND unit_price IS NOT NULL
GROUP BY category
ORDER BY estimated_net_value DESC;

-- Q105. Which cities have the most delivered orders?
SELECT city, COUNT(*) AS delivered_orders
FROM orders
WHERE order_status = 'Delivered'
  AND city IS NOT NULL
GROUP BY city
ORDER BY delivered_orders DESC
LIMIT 10;

-- Q106. Which payment method is used most often?
SELECT payment_method, COUNT(*) AS usage_count
FROM orders
WHERE payment_method IS NOT NULL
GROUP BY payment_method
ORDER BY usage_count DESC
LIMIT 1;

-- Q107. What percentage of orders are cancelled?
SELECT ROUND(
    100.0 * SUM(order_status = 'Cancelled') / COUNT(order_status), 2
) AS cancelled_percentage
FROM orders
WHERE order_status IS NOT NULL;

-- Q108. What is the average rating for delivered orders?
SELECT ROUND(AVG(rating), 2) AS average_delivered_rating
FROM orders
WHERE order_status = 'Delivered';

-- Q109. Which customers have the highest number of orders?
SELECT customer_id,
       COUNT(*) AS order_count
FROM orders
GROUP BY customer_id
ORDER BY order_count DESC
LIMIT 20;

-- Q110. What is monthly order volume and estimated net value?
SELECT DATE_FORMAT(order_date, '%Y-%m') AS order_month,
       COUNT(*) AS order_count,
       ROUND(SUM(quantity * unit_price *
           (1 - COALESCE(discount_percent, 0) / 100)), 2) AS estimated_net_value
FROM orders
WHERE order_date IS NOT NULL
  AND quantity IS NOT NULL
  AND unit_price IS NOT NULL
GROUP BY DATE_FORMAT(order_date, '%Y-%m')
ORDER BY order_month;

-- Q111. What percentage of orders have a rating of 4 or 5?
SELECT ROUND(
    100.0 * SUM(rating IN (4, 5)) / COUNT(rating), 2
) AS pct_rated_4_or_5
FROM orders
WHERE rating IS NOT NULL;

-- Q112. Compare order status by category.
SELECT category,
       SUM(order_status = 'Delivered') AS delivered,
       SUM(order_status = 'Cancelled') AS cancelled,
       SUM(order_status = 'Returned') AS returned,
       SUM(order_status = 'Shipped') AS shipped,
       SUM(order_status = 'Processing') AS processing
FROM orders
WHERE category IS NOT NULL
GROUP BY category
ORDER BY category;

